// Klasifikasi & Normalisasi Event Lengkap Ekalaya Laptop Store (Tahap 1-4)
const input = $json.body || $json;
const eventType = input.event || 'lead_captured';

if (eventType === 'daily_report_trigger') {
  // Tahap 3: Laporan Harian Pemilik Toko
  const m = input.metrics || {};
  return {
    eventType: 'LAPORAN_HARIAN',
    pesanWA: `📊 *LAPORAN HARIAN EKALAYA LAPTOP STORE*\nTanggal: ${m.date || new Date().toLocaleDateString('id-ID')}\n\n👥 Pengunjung: ${m.totalVisitors || '142'}\n📋 Total Leads: ${m.totalLeads || '18'}\n📦 Total Order: ${m.totalOrders || '6'}\n💰 Omset Harian: ${m.totalRevenue || 'Rp 114.700.000'}\n🔥 Unit Terlaris: ${m.topSellingUnit || 'ROG Titan X & ZenAir OLED'}\n\n_Laporan di-generate otomatis oleh n8n._`,
    timestamp: input.timestamp
  };
} else if (eventType === 'laptop_order_created') {
  // Tahap 2: Pesanan & Invoice Baru
  return {
    eventType: 'ORDER_BARU',
    invoiceNumber: input.invoiceNumber,
    buyerName: input.order.buyerName,
    buyerWhatsapp: input.order.buyerWhatsapp,
    laptopTitle: input.order.laptopTitle,
    price: input.order.price,
    paymentMethod: input.order.paymentMethod,
    address: input.order.buyerAddress,
    voucherCode: input.order.voucherCode,
    timestamp: input.timestamp
  };
} else if (eventType === 'laptop_payment_confirmed') {
  // Tahap 2: Pelunasan Pembayaran
  return {
    eventType: 'PEMBAYARAN_LUNAS',
    invoiceNumber: input.invoiceNumber,
    buyer: input.buyer,
    laptop: input.laptop,
    status: 'PAID',
    timestamp: input.timestamp
  };
} else if (eventType === 'referral_lead_captured') {
  // Tahap 4: Program Referral VIP
  return {
    eventType: 'REFERRAL_LEAD',
    referrer: input.referrer,
    leadName: input.leadName,
    leadWhatsapp: input.leadWhatsapp,
    bonusCommission: 'Rp 250.000',
    timestamp: input.timestamp
  };
} else {
  // Tahap 1: Lead Konsultasi Tamu
  const data = input.data || {};
  return {
    eventType: 'LEAD_KONSULTASI',
    fullName: data.fullName || 'Tamu Web',
    contact: data.contact || '-',
    laptopInterest: data.laptopInterest || 'Laptop Umum',
    budget: data.budget || '-',
    notes: data.notes || '-',
    timestamp: input.timestamp
  };
}
